//! The Prisma plan, search and coverage against the upstream oracle.
//!
//! `crates/prisma/tests/prisma-oracle.json` is generated by
//! `script/prisma-oracle.mjs` from the upstream `prismaPlan`, `prismaChanges`,
//! `getPrismaBonusMult` and `statueLevelingInputs`, so the Rust port is pinned
//! to the source of truth rather than to hand-picked numbers. The tiny save is
//! purpose-built for the status ladder and the ranking; the outcomes save puts
//! the STARTUE EXP bubble in a cauldron with no noisy neighbours; the committed
//! synthetic account is the realistic run.

use idleon_common::{Control, Progress};
use idleon_import::import;
use idleon_prisma::{self as prisma, Comparison, Outcome, Plan, Status};
use idleon_save::Save;
use serde_json::Value;

fn oracle() -> Value {
    serde_json::from_str(include_str!("prisma-oracle.json")).expect("the oracle JSON is valid")
}

fn save(path: &str) -> Save {
    let text = std::fs::read_to_string(path).expect("the save is committed");
    Save::new(serde_json::from_str(&text).expect("the save is valid JSON"))
}

fn fixture() -> Save {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../fixtures/data.json");
    let text = std::fs::read_to_string(path).expect("fixtures/data.json is committed");
    import(&text).expect("the fixture imports").save
}

fn tiny() -> Save {
    save(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/prisma-save.json"
    ))
}

fn outcomes() -> Save {
    save(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/prisma-outcomes-save.json"
    ))
}

fn status(id: &str) -> Status {
    match id {
        "ready" => Status::Ready,
        "already" => Status::Already,
        "ineligible" => Status::Ineligible,
        "unavailable" => Status::Unavailable,
        "unpurchased" => Status::Unpurchased,
        other => panic!("the oracle names an unknown status {other}"),
    }
}

fn comparison(id: &str) -> Comparison {
    match id {
        "added" => Comparison::Added,
        "retained" => Comparison::Retained,
        other => panic!("the oracle names an unknown comparison {other}"),
    }
}

/// One save's plan, row for row, against its oracle block.
fn check_plan(save: &Save, expected: &Value) {
    let characters = expected["characters"].as_array().expect("characters");
    let multiplier = expected["multiplier"].as_f64().expect("the multiplier");
    let blocks = expected["cauldrons"].as_object().expect("cauldrons");
    for (key, expected) in blocks {
        let cauldron: usize = key.parse().expect("a cauldron index");
        let plan = prisma::plan(save, 0, cauldron).expect("the save plans");
        assert_eq!(
            plan.multiplier, multiplier,
            "cauldron {cauldron}: the Prisma multiplier"
        );
        assert_eq!(plan.characters.len(), characters.len());
        for (character, expected) in plan.characters.iter().zip(characters) {
            assert_eq!(character.name, expected["name"].as_str().expect("a name"));
            assert_eq!(
                character.class_name,
                expected["className"].as_str().expect("a class name"),
                "character {}",
                character.index
            );
        }
        assert_eq!(plan.fragments, expected["fragments"].as_f64(), "fragments");
        assert_eq!(
            plan.map,
            expected["map"].as_f64().map(|map| map as usize),
            "map"
        );
        let rows = expected["rows"].as_array().expect("rows");
        assert_eq!(plan.rows.len(), rows.len(), "cauldron {cauldron} rows");
        for (row, expected) in plan.rows.iter().zip(rows) {
            let id = expected["id"].as_str().expect("a row id");
            assert_eq!(row.id, id);
            assert_eq!(row.name, expected["name"].as_str().expect("a row name"));
            assert_eq!(row.effect, expected["effect"].as_str().expect("an effect"));
            assert_eq!(row.level, expected["level"].as_f64(), "{id}: level");
            assert_eq!(
                row.status,
                status(expected["status"].as_str().expect("a status")),
                "{id}: status"
            );
            assert_eq!(
                row.comparable,
                expected["comparable"].as_bool().expect("comparable"),
                "{id}: comparable"
            );
            assert_eq!(
                row.reason,
                expected["reason"].as_str().expect("a reason"),
                "{id}: reason"
            );
            let base = expected["base"].as_f64().expect("a base bonus");
            assert!(
                (row.bonus - base).abs() <= 1e-9,
                "{id}: the bubble bonus is {} here, upstream {base}",
                row.bonus
            );
            let with_prisma = expected["withPrisma"].as_f64().expect("a Prisma bonus");
            assert!(
                (row.with_prisma(plan.multiplier) - with_prisma).abs() <= 1e-9,
                "{id}: the Prisma bonus is {}, upstream {with_prisma}",
                row.with_prisma(plan.multiplier)
            );
        }
    }
}

fn run(plan: &Plan) -> Outcome {
    let mut report = |_progress: Progress| Control::Continue;
    prisma::run(plan, &mut report).expect("the run finishes")
}

#[test]
fn the_synthetic_account_plans_like_the_upstream_oracle() {
    let oracle = oracle();
    check_plan(&fixture(), &oracle["saves"]["fixture"]);
}

#[test]
fn the_tiny_save_covers_the_status_ladder_like_upstream() {
    let oracle = oracle();
    check_plan(&tiny(), &oracle["saves"]["tiny"]);
    let plan = prisma::plan(&tiny(), 0, 0).expect("the tiny save plans");
    assert_eq!(plan.comparable(), 2);
    assert_eq!(plan.rows.len(), 34);
    assert_eq!(plan.cauldron_label(), "Power");
}

#[test]
fn the_outcomes_save_plans_like_the_upstream_oracle() {
    let oracle = oracle();
    check_plan(&outcomes(), &oracle["saves"]["outcomes"]);
    let plan = prisma::plan(&outcomes(), 0, 3).expect("the outcomes save plans");
    assert_eq!(plan.comparable(), 2);
}

/// Every modelled row's comparison, metric for metric, against upstream's
/// `prismaChanges` on the same save and candidate.
#[test]
fn every_row_compares_like_the_upstream_prisma_changes() {
    let oracle = oracle();
    for (name, save) in [
        ("fixture", fixture()),
        ("tiny", tiny()),
        ("outcomes", outcomes()),
    ] {
        let blocks = oracle["saves"][name]["comparisons"]
            .as_object()
            .expect("comparisons");
        for (cauldron, rows) in blocks {
            let cauldron: usize = cauldron.parse().expect("a cauldron index");
            let plan = prisma::plan(&save, 0, cauldron).expect("the save plans");
            let outcome = run(&plan);
            let rows = rows.as_array().expect("comparison rows");
            assert_eq!(
                outcome.results.len(),
                rows.len(),
                "{name}: cauldron {cauldron} comparable rows"
            );
            for expected in rows {
                let id = expected["id"].as_str().expect("a row id");
                let result = outcome
                    .results
                    .iter()
                    .find(|result| result.row.id == id)
                    .unwrap_or_else(|| panic!("{name}: {id} has no result"));
                assert_eq!(
                    result.comparison,
                    comparison(expected["comparison"].as_str().expect("a comparison")),
                    "{name}: {id}: comparison"
                );
                if let Some(error) = expected["error"].as_str() {
                    // Upstream's sandbox re-checks ownership and rejects the
                    // fixture's `0c9,` entry that the plan's substring test
                    // counts as Prisma-ed; its run stores an error row instead
                    // of a comparison.
                    assert!(!error.is_empty(), "{name}: {id}: error text");
                    continue;
                }
                check_changes(
                    result,
                    expected["changes"].as_array().expect("changes"),
                    name,
                    id,
                );
                check_intermediate(result, &plan, name, id);
            }
        }
    }
}

fn check_changes(result: &prisma::RowResult, expected: &[Value], save: &str, id: &str) {
    assert_eq!(
        result.changes.len(),
        expected.len(),
        "{save}: {id}: downstream changes"
    );
    for (change, expected) in result.changes.iter().zip(expected) {
        let metric = expected["id"].as_str().expect("a metric id");
        assert_eq!(change.id, metric, "{save}: {id}: metric");
        assert_eq!(
            change.name,
            expected["name"].as_str().expect("a metric name"),
            "{save}: {id}: {metric}: name"
        );
        for (field, actual, expected) in [
            ("before", change.before, expected["before"].as_f64()),
            ("after", change.after, expected["after"].as_f64()),
            ("delta", change.delta, expected["delta"].as_f64()),
        ] {
            let expected = expected.unwrap_or_else(|| panic!("{save}: {id}: {metric} {field}"));
            assert!(
                (actual - expected).abs() <= 1e-9,
                "{save}: {id}: {metric} {field} is {actual} here, upstream {expected}"
            );
        }
        let expected = expected["percent"].as_f64();
        match (change.percent, expected) {
            (Some(actual), Some(expected)) => assert!(
                (actual - expected).abs() <= 1e-9,
                "{save}: {id}: {metric} percent is {actual} here, upstream {expected}"
            ),
            (None, None) => {}
            other => panic!("{save}: {id}: {metric} percent is {other:?}"),
        }
        assert!(!change.intermediate, "{save}: {id}: {metric}");
    }
}

/// The processed bonus is always an intermediate, and always the benefit adding
/// (or keeping) this bubble's Prisma buys.
fn check_intermediate(result: &prisma::RowResult, plan: &Plan, save: &str, id: &str) {
    assert_eq!(
        result.intermediates.len(),
        1,
        "{save}: {id}: the bubble bonus moved"
    );
    let change = &result.intermediates[0];
    assert_eq!(change.id, format!("bubble-bonus:{id}"), "{save}: {id}");
    assert!(change.intermediate);
    assert_eq!(
        (change.before, change.after),
        (result.row.bonus, result.row.with_prisma(plan.multiplier))
    );
    assert!(
        change.after > change.before,
        "{save}: {id}: the bonus grows"
    );
}

#[test]
fn the_statue_retention_outcome_ranks_the_startue_bubble_first() {
    let plan = prisma::plan(&fixture(), 0, 3).expect("the fixture plans");
    let outcome = run(&plan);
    let ranked: Vec<&str> = outcome
        .rank("statue-retention")
        .iter()
        .map(|result| result.row.id.as_str())
        .collect();
    assert_eq!(
        ranked.first(),
        Some(&"3:2"),
        "STARTUE EXP is the only bubble a modelled outcome reads"
    );
    assert!(
        ranked.len() > 20,
        "the rest of the cauldron keeps a zero score"
    );
    let statue = outcome
        .results
        .iter()
        .find(|result| result.row.id == "3:2")
        .expect("the STARTUE EXP row");
    assert_eq!(statue.comparison, Comparison::Retained);
    let change = statue
        .change("statue-retention")
        .expect("the retained retention benefit");
    assert!((change.before - 24.925_280_199_252_796).abs() <= 1e-9);
    assert!((change.after - 50.0).abs() <= 1e-9);
    assert!((change.delta - 25.074_719_800_747_204).abs() <= 1e-9);
    assert!(
        change
            .percent
            .is_some_and(|percent| (percent - 100.599_550_337_247_1).abs() <= 1e-9)
    );
    // Every other row still shows the outcome, with a zero delta.
    for result in &outcome.results {
        let view = result
            .view("statue-retention")
            .expect("every row shows the outcome");
        if result.row.id != "3:2" {
            assert_eq!(view.delta, 0.0, "{}: unchanged outcome", result.row.id);
        }
    }
}

#[test]
fn the_fixture_search_reports_every_comparable_bubble_and_its_coverage() {
    let plan = prisma::plan(&fixture(), 0, 0).expect("the fixture plans");
    let outcome = run(&plan);
    assert_eq!(outcome.results.len(), plan.comparable());
    assert!(
        outcome.results.len() > 20,
        "the fixture has most bubbles owned"
    );
    assert!(outcome.baseline.len() > 20);
    for result in &outcome.results {
        assert!(
            !result.intermediates.is_empty(),
            "{}: a comparison changes its bubble bonus",
            result.row.id
        );
        assert_eq!(result.intermediates.len(), 1);
        assert!(
            result.changes.is_empty(),
            "{}: Power has no modelled downstream outcome",
            result.row.id
        );
        assert!(result.matches(&result.row.name));
        assert!(result.matches(&result.row.effect));
    }
    assert_eq!(outcome.coverage.modelled(), 0);
    assert_eq!(outcome.coverage.missing(), outcome.coverage.total());
    assert!(
        outcome.coverage.total() >= 29,
        "the fixture carries many effects"
    );
    for entry in &outcome.coverage.effects {
        if let Some(consumer) = entry.consumers.first() {
            assert!(!consumer.method.is_empty(), "{}", entry.effect);
        }
    }

    let plan = prisma::plan(&fixture(), 0, 3).expect("the fixture plans");
    let outcome = run(&plan);
    assert_eq!(outcome.coverage.modelled(), 1);
    let statue = outcome
        .coverage
        .effects
        .iter()
        .find(|entry| entry.effect == "StatueStartEXP")
        .expect("the STARTUE EXP effect");
    assert!(statue.modelled());
    assert_eq!(statue.metrics, ["statue-retention"]);
    assert_eq!(statue.bubbles, ["Startue Exp"]);
    assert!(
        statue
            .consumers
            .iter()
            .any(|consumer| consumer.method == "_event_StatueBars")
    );
    let unmodelled = outcome
        .coverage
        .effects
        .iter()
        .find(|entry| !entry.modelled())
        .expect("a missing downstream system");
    assert!(unmodelled.metrics.is_empty());
}
